+                _mm256_and_ps(_mm256_cmp_ps(x2, x2, _CMP_ORD_Q), _mm256_cmp_ps(x3, x3, _CMP_ORD_Q)));
+            if (_mm256_movemask_ps(valid) != 255) return false;
+            const __m256 peaks = _mm256_max_ps(
+                _mm256_max_ps(_mm256_andnot_ps(sign, x0), _mm256_andnot_ps(sign, x1)),
+                _mm256_max_ps(_mm256_andnot_ps(sign, x2), _mm256_andnot_ps(sign, x3)));
+            __m128 peak4 = _mm_max_ps(_mm256_castps256_ps128(peaks), _mm256_extractf128_ps(peaks, 1));
