+            q16_scales_[b] = scale;
+            const __m256 inv = _mm256_set1_ps(inverse);
+            const auto quantize = [&](const __m256 values) {
+                return _mm256_cvttps_epi32(_mm256_round_ps(_mm256_mul_ps(values, inv),
+                    _MM_FROUND_TO_NEAREST_INT | _MM_FROUND_NO_EXC));
+            };
