#include "model/arch_qwen.hpp"
#include <fstream>
#include <iostream>
#include <stdexcept>

static void check(bool ok, const char* message) { if (!ok) throw std::runtime_error(message); }
static void report(const char* phase, const std::vector<float>& logits, bool grouped) {
    using namespace backend::q16_witness;
    for (float v : logits) check(std::isfinite(v), "nonfinite logits");
    check(!logits.empty(), "empty logits");
    check(get(standalone_packs) > 0 && get(standalone_integer_rows) > 0, "missing standalone activation");
    check((get(group_packs) > 0) == grouped && (get(group_integer_rows) > 0) == grouped, "unexpected grouped activation");
    check(get(group_float_rows) == 0 && get(standalone_float_rows) == 0, "unexpected Q16 fallback");
    std::cout << phase;
    for (int i = 0; i < count; ++i) std::cout << ' ' << counters[i].load(std::memory_order_relaxed);
    std::cout << '\n';
}
int main(int argc, char** argv) {
    try {
        if (argc != 3) throw std::runtime_error("usage: model-witness model.gguf tokens-247.txt");
        std::ifstream input(argv[2]);
